package net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.SmtpOutboundConfig;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueobject.SenderNameVO;

class SenderNameValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of sender name of smtp outbound config")
  void test_sender_name_value_holder_assign_plain_value() {
    Object holder = new Object();
    SenderNameValueHolder<Object> value = new SenderNameValueHolder<>(holder);
    Assertions.assertSame(holder, value.senderName("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getSenderNameValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getSenderName().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.senderNameNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getSenderNameValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getSenderName().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of sender name of smtp outbound config")
  void test_sender_name_value_holder_assign_value_object() {
    Object holder = new Object();
    SenderNameValueHolder<Object> value = new SenderNameValueHolder<>(holder);
    SenderNameVO vo = SenderNameVO.from("one");
    Assertions.assertFalse(value.getSenderNameValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.senderName(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getSenderNameValue().orElseThrow());
    Assertions.assertSame(holder, value.senderName(Optional.empty()));
    Assertions.assertFalse(value.getSenderNameValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.senderName(Optional.of(vo)));
    Assertions.assertSame(vo, value.getSenderNameValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of sender name of smtp outbound config against the original")
  void test_sender_name_value_holder_read() {
    Object holder = new Object();
    SenderNameValueHolder<Object> value = new SenderNameValueHolder<>(holder);
    SenderNameVO vo = SenderNameVO.from("one");
    SenderNameVO other = SenderNameVO.from("one");
    SmtpOutboundConfig original = Mockito.mock(SmtpOutboundConfig.class);
    Mockito.when(original.getSenderNameValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readSenderName(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readSenderName(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.senderName(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readSenderName(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readSenderName(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of sender name of smtp outbound config")
  void test_sender_name_value_holder_unset() {
    Object holder = new Object();
    SenderNameValueHolder<Object> value = new SenderNameValueHolder<>(holder);
    SenderNameVO vo = SenderNameVO.from("one");
    value.senderName(vo);
    Assertions.assertSame(holder, value.unsetSenderNameIfMatches("senderName_other"));
    Assertions.assertTrue(value.getSenderNameValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetSenderNameIfMatches("senderName"));
    Assertions.assertFalse(value.getSenderNameValue().isPresent(),
        "The field name must clear the value");
    value.senderName(vo);
    Assertions.assertSame(holder, value.unsetSenderName());
    Assertions.assertFalse(value.getSenderNameValue().isPresent(), "Unset must clear the value");
  }
}
